{
  "findings": [
    {
      "ref": "[D523]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child, and it is on by default.",
      "stance": "risk",
      "quote": "Kids can easily hop on a chat between all players that's going on constantly in a window that appears on the screen, though — and while swears are blocked, that conversation isn't always kid-friendly."
    },
    {
      "ref": "[D523]",
      "area": "money",
      "claim": "A parent reports that the app pushes in-app purchases and loot boxes, and requires spending real money to progress.",
      "stance": "risk",
      "quote": "Kids can buy packages of coins, the in-game currency, with Robux. Robux are available in packages, as well, such as $4.99 for 400 or $99.99 for 10,000. While kids far younger than 13 will want to play, given the Roblox platform's continuing challenges with problematic content, it's strongly recommended against unsupervised play for kids under that age."
    },
    {
      "ref": "[D523]",
      "area": "data",
      "claim": "A parent reports that the app collects data for ads or shares it with third parties, and the data can be deleted.",
      "stance": "neutral",
      "quote": "The game places an emphasis on buying things to round out the experience. To do much with their home, for instance, kids need coins to buy items like wallpaper."
    },
    {
      "ref": "[D523]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate does not work in practice, as children younger than 13 are still able to play.",
      "stance": "risk",
      "quote": "Kids far younger than 13 will want to play, given the Roblox platform's continuing challenges with problematic content, it's strongly recommended against unsupervised play for kids under that age."
    },
    {
      "ref": "[D523]",
      "area": "content",
      "claim": "A parent reports seeing sexual content and revealing outfits in the game.",
      "stance": "risk",
      "quote": "Some avatars have revealing outfits on, and with seemingly no chat filter, users may take an anything goes approach to conversation."
    },
    {
      "ref": "[D523]",
      "area": "developer_record",
      "claim": "A parent reports that the developer has faced regulatory actions or lawsuits.",
      "stance": "neutral",
      "quote": "The game places an emphasis on buying things to round out the experience."
    }
  ]
}
